"motion_js": "export const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
export const lerp = (a, b, t) => a + (b - a) * t;
export const lerp3 = (a, b, t) => https://a.map/((v, i) => lerp(v, b[i], t));
export const ramp = (f, a, b) => clamp((f - a) / (b - a));
export const M = {
smooth: (t) => { t = clamp(t); return t * t * t * (t * (t * 6 - 15) + 10); }, 
easeOut: (t) => 1 - Math.pow(1 - clamp(t), 3), 
easeIn: (t) => Math.pow(clamp(t), 3),
back: (t, s = 1.7) => { t = clamp(t) - 1; return t * t * ((s + 1) * t + s) + 1; }, 
anticip: (t, s = 0.12) => { t = clamp(t); return t < 0.25 ? -s * Math.sin(t / 0.25 * Math.PI) : M.back((t - 0.25) / 0.75); }, 
