"creature_template_js": "const EMU = { body: "#4d3b2c", bodyDk: "#2f241b", streak: "#7a6048", neck: "#7f90ad", neckDk: "#56627c", head: "#3a2f28", beak: "#cdb68e", leg: "#8c8780", legDk: "#5e5a55" };
